SELECT time, filemod_name, access, pid, process_name FROM audit_logs WHERE process_name LIKE '%winword.exe%' AND filemod_name IS NOT NULL AND (
  filemod_name LIKE 'C:\\Users\\aalsahee\\AppData\\Local\\Temp%' OR
  filemod_name LIKE 'C:\\Users\\aalsahee\\AppData\\Roaming\\Microsoft\\Templates%' OR
  filemod_name LIKE 'C:\\Users\\aalsahee\\AppData\\Roaming\\Microsoft\\Word\\Startup%'
) AND time BETWEEN '2022-07-20 00:48:57' AND '2022-07-20 00:56:22'
ORDER BY time;

